// ===== Keystone shared library (generated from ops/lib; do not edit here) =====
const __KS = (() => {
  const defs = {
  'reporting': function (module, exports, require) {
'use strict';
// Reporting: Xero numbers + Keystone activity -> one weekly metrics row per client,
// plus the plain-English explainer agent.

const { obj } = require('./agent');

function amount(cell) {
  const v = cell && cell.Value !== undefined ? cell.Value : cell;
  const n = Number(String(v || '').replace(/[,£]/g, ''));
  return isFinite(n) ? n : 0;
}

// Walks a Xero Reports API response and returns {label -> first numeric cell}.
function flattenXeroReport(report) {
  const rep = report && report.Reports ? report.Reports[0] : report;
  const out = {};
  const walk = (rows) => {
    for (const r of rows || []) {
      if (r.Rows) walk(r.Rows);
      if ((r.RowType === 'Row' || r.RowType === 'SummaryRow') && r.Cells && r.Cells.length > 1) {
        const label = String(r.Cells[0].Value || '').trim().toLowerCase();
        if (label && out[label] === undefined) out[label] = amount(r.Cells[1]);
      }
    }
  };
  walk(rep && rep.Rows);
  return out;
}

function parseProfitAndLoss(report) {
  const f = flattenXeroReport(report);
  const pick = (...labels) => { for (const l of labels) if (f[l] !== undefined) return f[l]; return 0; };
  const revenue = pick('total income', 'total trading income', 'total revenue', 'total sales');
  const cos = pick('total cost of sales', 'total direct costs');
  const opex = pick('total operating expenses', 'total expenses');
  const net = f['net profit'] !== undefined ? f['net profit'] : revenue - cos - opex;
  return { revenue, costs: cos + opex, netProfit: net };
}

function parseBankSummary(report) {
  const f = flattenXeroReport(report);
  // Bank Summary rows: account | opening | received | spent | closing. Use the closing-balance total.
  const rep = report && report.Reports ? report.Reports[0] : report;
  let closing = null;
  const walk = (rows) => {
    for (const r of rows || []) {
      if (r.Rows) walk(r.Rows);
      if (r.RowType === 'SummaryRow' && r.Cells && r.Cells.length >= 5) closing = amount(r.Cells[r.Cells.length - 1]);
    }
  };
  walk(rep && rep.Rows);
  return { cash: closing !== null ? closing : f['total'] || 0 };
}

// invoices: Xero ACCREC invoices with Status AUTHORISED (approved and awaiting payment).
function parseReceivables(invoices, today) {
  const t = (today || new Date()).toISOString().slice(0, 10);
  let receivables = 0, overdueCount = 0, overdueValue = 0;
  const overdue = [];
  for (const inv of invoices || []) {
    if (inv.Type && inv.Type !== 'ACCREC') continue;
    if (inv.Status !== 'AUTHORISED') continue;
    const due = amount(inv.AmountDue);
    if (due <= 0) continue;
    receivables += due;
    const dueDate = xeroDate(inv.DueDateString || inv.DueDate);
    if (dueDate && dueDate < t) {
      overdueCount++; overdueValue += due;
      overdue.push({ number: inv.InvoiceNumber, contact: inv.Contact && inv.Contact.Name, due, dueDate, daysLate: Math.round((Date.parse(t) - Date.parse(dueDate)) / 86400000) });
    }
  }
  overdue.sort((a, b) => b.due - a.due);
  return { receivables: round(receivables), overdueCount, overdueValue: round(overdueValue), topOverdue: overdue.slice(0, 5) };
}

function xeroDate(v) {
  if (!v) return null;
  const m = String(v).match(/\/Date\((\d+)/);
  if (m) return new Date(Number(m[1])).toISOString().slice(0, 10);
  return String(v).slice(0, 10);
}

function round(n) { return Math.round(n * 100) / 100; }

// Keystone activity for one client in [from, to). All inputs must already be filtered to that client.
function activityCounts({ agentLog = [], callLog = [], quotes = [] }, from, to, clientId) {
  const inRange = (ts) => { const d = Date.parse(ts); return d >= Date.parse(from) && d < Date.parse(to); };
  const f = (r) => (r.fields ? r.fields : r);
  const mine = (r) => f(r)['Client ID'] === clientId;
  const logs = agentLog.filter(mine).map(f).filter((r) => inRange(r['Timestamp']));
  const calls = callLog.filter(mine).map(f).filter((r) => inRange(r['Timestamp']));
  const qs = quotes.filter(mine).map(f).filter((r) => inRange(r['Created']));
  const cat = (r) => (r['Category'] && r['Category'].name) || r['Category'];
  const outcome = (r) => (r['Outcome'] && r['Outcome'].name) || r['Outcome'];
  return {
    invoicesDrafted: logs.filter((r) => String(r['Event']).startsWith('invoice_') && outcome(r) === 'Draft created').length,
    invoicesToReview: logs.filter((r) => String(r['Event']).startsWith('invoice_') && outcome(r) === 'Sent to review').length,
    callsHandled: calls.length,
    bookingsMade: calls.filter((r) => ['Booking', 'Reschedule'].includes(cat(r))).length,
    urgentCalls: calls.filter((r) => cat(r) === 'Urgent').length,
    complaints: calls.filter((r) => cat(r) === 'Complaint').length,
    quotesIssued: qs.length,
    issuesAutoFixed: logs.filter((r) => outcome(r) === 'Auto-fixed').length,
    escalations: logs.filter((r) => outcome(r) === 'Escalated').length,
    minutesSaved: logs.reduce((s, r) => s + (Number(r['Minutes saved']) || 0), 0),
  };
}

// Deterministic, realistic demo figures (no Xero needed). Seeded by client + week so reruns match.
function demoFinancials(clientId, weekStart) {
  let seed = 0;
  for (const ch of clientId + weekStart) seed = (seed * 31 + ch.charCodeAt(0)) >>> 0;
  const rnd = () => { seed = (seed * 1664525 + 1013904223) >>> 0; return seed / 4294967296; };
  const revenue = Math.round(68000 + rnd() * 24000);
  const costs = Math.round(revenue * (0.74 + rnd() * 0.12));
  const receivables = Math.round(revenue * (1.4 + rnd() * 0.6));
  const overdueCount = 3 + Math.floor(rnd() * 7);
  return {
    revenue, costs, netProfit: revenue - costs,
    cash: Math.round(90000 + rnd() * 60000),
    receivables, overdueCount, overdueValue: Math.round(receivables * (0.18 + rnd() * 0.15)),
    topOverdue: [
      { number: 'INV-2041', contact: 'Harbour Lettings Ltd', due: 4820, daysLate: 38 },
      { number: 'INV-2077', contact: 'St Anne\'s School', due: 2150, daysLate: 21 },
      { number: 'INV-2093', contact: 'R. Patel', due: 640, daysLate: 9 },
    ],
  };
}

const EXPLAINER_SCHEMA = obj({
  subject: { type: 'string' },
  headline: { type: 'string' },
  whatChanged: { type: 'array', items: { type: 'string' } },
  why: { type: 'array', items: { type: 'string' } },
  actions: { type: 'array', items: obj({ action: { type: 'string' }, reason: { type: 'string' } }) },
});

const EXPLAINER_SYSTEM = `You write a short weekly money update for the owner of a UK small business who is not an accountant.
Rules:
- Plain English, no jargon. Say "money owed to you", not "receivables", and "money in the bank", not "cash position".
- Use only the numbers provided. Don't invent figures. Round to the nearest £100 in prose.
- whatChanged: 2-4 bullets comparing this week with last week.
- why: 1-3 bullets with the most likely reasons, based on the data. If the data can't explain a change, say so.
- actions: 1-3 concrete things to do this week, most valuable first. Never tell them to take out loans, finance or credit; suggest operational actions instead.
- Warm and direct. The subject line is at most 70 characters.`;

function explainerPrompt(client, current, previous, activity) {
  return `Business: ${client.clientName} (${client.industry})
This week: ${JSON.stringify(current)}
Last week: ${JSON.stringify(previous || 'no data yet')}
What Keystone did this week: ${JSON.stringify(activity)}`;
}

// Used when the AI call fails, so the client still gets a useful email.
function fallbackExplainer(client, cur, prev) {
  const gbp = (n) => '£' + Math.round(n / 100) * 100;
  const diff = (a, b) => (b === undefined || b === null ? '' : a >= b ? ` (up ${gbp(a - b)} on last week)` : ` (down ${gbp(b - a)} on last week)`);
  const p = prev || {};
  return {
    subject: `${client.clientName}: your week in numbers`,
    headline: `Money in the bank is ${gbp(cur.cash)}${diff(cur.cash, p.cash)}.`,
    whatChanged: [
      `Sales this week: ${gbp(cur.revenue)}${diff(cur.revenue, p.revenue)}.`,
      `Money owed to you: ${gbp(cur.receivables)}, of which ${gbp(cur.overdueValue)} is overdue across ${cur.overdueCount} invoices.`,
    ],
    why: ['This summary was generated without the AI explainer, so the reasons are not analysed this week.'],
    actions: cur.overdueCount ? [{ action: `Chase the ${Math.min(3, cur.overdueCount)} largest overdue invoices`, reason: `${gbp(cur.overdueValue)} is waiting to be paid.` }] : [{ action: 'No overdue invoices. Keep invoicing on the day the job finishes.', reason: 'Fast invoicing keeps cash coming in.' }],
  };
}

module.exports = { flattenXeroReport, parseProfitAndLoss, parseBankSummary, parseReceivables, xeroDate, activityCounts, demoFinancials, EXPLAINER_SCHEMA, EXPLAINER_SYSTEM, explainerPrompt, fallbackExplainer };

  },
  'agent': function (module, exports, require) {
'use strict';
// Claude API helpers for n8n HTTP Request nodes (raw HTTP: n8n has no SDK).
// The request asks for JSON matching a schema (structured outputs). The response
// parser checks for refusals and bad JSON and never throws, so every caller can
// fail safe: send the case to human review instead of guessing.

const AI = require('./ai');
const DEFAULT_MODEL = 'claude-opus-5-5';
const API_URL = 'https://api.anthropic.com/v1/messages';
const HEADERS = {
  'anthropic-version': '2026-10-21',
  'anthropic-beta': 'server-side-fallback-2026-07-01',
  'content-type': 'application/json',
};

// task picks the model (see ai.js): Haiku for routine work, Opus for audits and finance decisions.
// tools: optional server tools, e.g. web search for research agents.
function buildClaudeRequest({ system, prompt, schema, effort = 'medium', maxTokens = 8000, model, task, tools }) {
  const m = model || (task ? AI.modelFor(task) : DEFAULT_MODEL);
  const body = {
    model: m,
    max_tokens: maxTokens,
    system,
    messages: [{ role: 'user', content: prompt }],
    output_config: { effort },
  };
  // Server-side refusal fallback exists for Opus/Sonnet/Fable, not Haiku.
  if (!/haiku/.test(m)) body.fallbacks = 'default';
  if (schema) body.output_config.format = { type: 'json_schema', schema };
  if (tools && tools.length) body.tools = tools;
  return { url: API_URL, headers: HEADERS, body };
}

// Web search server tool. Haiku uses the basic version; Opus/Sonnet the newer one with filtering.
function webSearchTool(model, maxUses = 6, extra = {}) {
  const basic = /haiku/.test(String(model));
  return { type: basic ? 'web_search_20250305' : 'web_search_20260209', name: 'web_search', max_uses: maxUses, ...extra };
}

function parseClaudeJson(response) {
  if (!response || typeof response !== 'object') return { ok: false, error: 'no_response' };
  if (response.type === 'error' || response.error) {
    return { ok: false, error: 'api_error', detail: (response.error && response.error.message) || JSON.stringify(response.error) };
  }
  if (response.stop_reason === 'refusal') return { ok: false, error: 'refusal' };
  if (response.stop_reason === 'max_tokens') return { ok: false, error: 'truncated' };
  if (response.stop_reason === 'pause_turn') return { ok: false, error: 'paused' };
  // With web search the answer can come after several tool blocks: the JSON is in the last text run.
  const blocks = response.content || [];
  let lastTool = -1;
  blocks.forEach((b, i) => { if (b.type !== 'text') lastTool = i; });
  const text = blocks.slice(lastTool + 1).filter((b) => b.type === 'text').map((b) => b.text).join('') || blocks.filter((b) => b.type === 'text').map((b) => b.text).join('');
  if (!text) return { ok: false, error: 'empty' };
  try {
    return { ok: true, data: JSON.parse(text), model: response.model };
  } catch (e) {
    const a = text.indexOf('{'), b = text.lastIndexOf('}');
    if (a >= 0 && b > a) { try { return { ok: true, data: JSON.parse(text.slice(a, b + 1)), model: response.model }; } catch (e2) { /* fall through */ } }
    return { ok: false, error: 'invalid_json', detail: text.slice(0, 500) };
  }
}

// Helper for strict JSON schemas: every property required, no extras.
function obj(properties, required) {
  return { type: 'object', properties, required: required || Object.keys(properties), additionalProperties: false };
}

module.exports = { DEFAULT_MODEL, API_URL, HEADERS, buildClaudeRequest, webSearchTool, parseClaudeJson, obj };

  },
  'ai': function (module, exports, require) {
'use strict';
// Which Claude model each job uses, what it costs, and the monthly budget rules.
//  - Routine agent work (summaries, drafts, research, explainers) -> Claude Haiku 5.5 (cheap, fast).
//  - Client audits and finance decisions (invoice fixes, proposals and pricing, CFO review) -> Claude Opus 5.5.
//  - Every call is logged to Airtable "AI Usage" with its cost.
//  - At 80% of the monthly credit Bilal is alerted. Over 100%, non-urgent work is queued until there is room.
//    Customer-facing work (phone, quotes, invoices) is never queued: it either runs or uses its non-AI fallback.

const MODELS = { routine: 'claude-haiku-5-5', strong: 'claude-opus-5-5' };

// task -> tier. Anything not listed is routine.
const TASKS = {
  audit_report: 'strong',
  invoice_exception: 'strong',
  proposal: 'strong',
  cfo_review: 'strong',
  quote_estimate: 'routine',
  weekly_explainer: 'routine',
  lead_research: 'routine',
  outreach_draft: 'routine',
  call_brief: 'routine',
  chief_brief: 'routine',
  chief_scorecard: 'routine',
  onboarding_check: 'routine',
  client_success: 'routine',
  content_draft: 'routine',
  compliance_check: 'routine',
  systems_review: 'routine',
};

// Never queued: a customer, client or prospect is waiting (each of these also has a non-AI fallback).
const URGENT = new Set(['invoice_exception', 'quote_estimate', 'audit_report', 'weekly_explainer']);

// US dollars per million tokens (Anthropic first-party list prices). cacheWrite = 5-minute writes.
const PRICES = {
  'claude-haiku-5-5': { input: 0.10, output: 0.50, cacheRead: 0.01, cacheWrite: 0.125, long: { input: 0.50, output: 2.50, cacheRead: 0.05, cacheWrite: 0.625 }, longAbove: 100000 },
  'claude-opus-5-5': { input: 4, output: 20, cacheRead: 0.20, cacheWrite: 5 },
  'claude-sonnet-5-5': { input: 2, output: 10, cacheRead: 0.20, cacheWrite: 2.5 },
  'claude-opus-5': { input: 5, output: 25, cacheRead: 0.50, cacheWrite: 6.25 },
  'claude-fable-5-1': { input: 10, output: 50, cacheRead: 0.25, cacheWrite: 12.5 },
};
const WEB_SEARCH_USD = 0.01; // $10 per 1,000 searches

function tierOf(task) { return TASKS[task] || 'routine'; }
function modelFor(task) { return MODELS[tierOf(task)]; }
function isUrgent(task) { return URGENT.has(task); }

function priceFor(model) {
  const m = String(model || '');
  if (PRICES[m]) return PRICES[m];
  const key = Object.keys(PRICES).find((k) => m.startsWith(k));
  return key ? PRICES[key] : PRICES['claude-opus-5-5']; // unknown model: price high, never under-count
}

// Cost of one usage block. Haiku switches to its long-prompt card above 100K prompt tokens.
function usageCost(usage, model) {
  const u = usage || {};
  const p0 = priceFor(model);
  const inTok = Number(u.input_tokens) || 0;
  const cr = Number(u.cache_read_input_tokens) || 0;
  const cw = Number(u.cache_creation_input_tokens) || 0;
  const out = Number(u.output_tokens) || 0;
  const p = p0.long && inTok + cr + cw > p0.longAbove ? p0.long : p0;
  const searches = Number(u.server_tool_use && u.server_tool_use.web_search_requests) || 0;
  return (inTok * p.input + cr * p.cacheRead + cw * p.cacheWrite + out * p.output) / 1e6 + searches * WEB_SEARCH_USD;
}

// Cost of a whole response. If a server-side fallback ran, usage.iterations lists each model's share.
function costOf(response) {
  if (!response || typeof response !== 'object' || !response.usage) return 0;
  const its = Array.isArray(response.usage.iterations) ? response.usage.iterations.filter((x) => x && (x.input_tokens || x.output_tokens)) : [];
  if (its.length) {
    const searches = Number(response.usage.server_tool_use && response.usage.server_tool_use.web_search_requests) || 0;
    return its.reduce((s, x) => s + usageCost({ ...x, server_tool_use: null }, x.model || response.model), 0) + searches * WEB_SEARCH_USD;
  }
  return usageCost(response.usage, response.model);
}

function round4(n) { return Math.round((Number(n) || 0) * 10000) / 10000; }

// Airtable "AI Usage" row for one Claude call (also for failed calls: tokens may still be billed).
function usageRecord({ response, task, agent, workflow, clientId, executionId, outcome, now }) {
  const r = response && typeof response === 'object' ? response : {};
  const u = r.usage || {};
  const model = r.model || modelFor(task);
  const ts = (now || new Date()).toISOString();
  return {
    'Run': `${agent || workflow || 'ai'} · ${task} · ${ts.slice(0, 16).replace('T', ' ')}`,
    'Timestamp': ts,
    'Agent': agent || '',
    'Workflow': workflow || '',
    'Client ID': clientId || '',
    'Task': task,
    'Tier': tierOf(task) === 'strong' ? 'Strong (Opus)' : 'Routine (Haiku)',
    'Model': model,
    'Input tokens': (Number(u.input_tokens) || 0) + (Number(u.cache_read_input_tokens) || 0) + (Number(u.cache_creation_input_tokens) || 0),
    'Output tokens': Number(u.output_tokens) || 0,
    'Web searches': Number(u.server_tool_use && u.server_tool_use.web_search_requests) || 0,
    'Cost USD': round4(costOf(r)),
    'Outcome': outcome || (r.usage ? 'OK' : 'No response'),
    'Execution ID': executionId ? String(executionId) : '',
  };
}

// ---------- monthly budget ----------
function monthKey(d) { return (d || new Date()).toISOString().slice(0, 7); }

function budgetStatus(spentUsd, creditUsd, alertPct) {
  const credit = Number(creditUsd) || 0;
  if (!credit) return { status: 'ok', pct: 0 };
  const pct = (Number(spentUsd) || 0) / credit * 100;
  const warnAt = Number(alertPct) || 80;
  return { status: pct >= 100 ? 'over' : pct >= warnAt ? 'warning' : 'ok', pct: Math.round(pct * 10) / 10 };
}

// Should this task call Claude now? S = Keystone Settings map.
function gate(S, task) {
  const status = String((S && S.ai_status) || 'ok').toLowerCase();
  const sameMonth = !S || !S.ai_spend_month || S.ai_spend_month === monthKey();
  if (status === 'over' && sameMonth && !isUrgent(task)) return { allow: false, reason: 'Monthly AI credit used up: queued until there is room.' };
  return { allow: true };
}

// Alert decisions for the budget workflow. Returns which alerts to send now (each once per month).
function budgetAlerts(S, status, pct, month) {
  const out = [];
  if (pct >= (Number(S.ai_alert_pct) || 80) && S.ai_alert_80_sent !== month) out.push({ level: 80, key: 'ai_alert_80_sent' });
  if (pct >= 100 && S.ai_alert_100_sent !== month) out.push({ level: 100, key: 'ai_alert_100_sent' });
  return out;
}

module.exports = { MODELS, TASKS, PRICES, WEB_SEARCH_USD, tierOf, modelFor, isUrgent, priceFor, usageCost, costOf, usageRecord, monthKey, budgetStatus, gate, budgetAlerts, round4 };

  },
  'render': function (module, exports, require) {
'use strict';
// Branded HTML for emails and the client dashboard. Inline CSS only (email-safe).

const { escapeHtml: e } = require('./log');

const gbp = (n) => '£' + Number(n || 0).toLocaleString('en-GB', { minimumFractionDigits: 0, maximumFractionDigits: 2 });

function shell(client, title, body) {
  const colour = /^#[0-9a-f]{3,8}$/i.test(client.invoice.brandColour) ? client.invoice.brandColour : '#1F3A5F';
  const logo = client.invoice.brandLogoUrl ? `<img src="${e(client.invoice.brandLogoUrl)}" alt="${e(client.clientName)}" style="max-height:48px;max-width:200px">` : `<strong style="font-size:20px;color:#fff">${e(client.clientName)}</strong>`;
  return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${e(title)}</title></head>
<body style="margin:0;background:#f4f5f7;font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;color:#1d2433">
<div style="max-width:680px;margin:0 auto;padding:16px">
<div style="background:${colour};padding:18px 20px;border-radius:10px 10px 0 0">${logo}</div>
<div style="background:#fff;padding:22px 20px;border-radius:0 0 10px 10px;line-height:1.5">${body}</div>
<p style="font-size:12px;color:#6b7280;text-align:center">Run by Keystone, your outsourced operations team.</p>
</div></body></html>`;
}

function table(rows, head) {
  const th = head ? `<tr>${head.map((h, i) => `<th style="text-align:${i ? 'right' : 'left'};padding:8px;border-bottom:2px solid #e5e7eb;font-size:13px;color:#6b7280">${e(h)}</th>`).join('')}</tr>` : '';
  return `<table style="width:100%;border-collapse:collapse;font-size:14px">${th}${rows.map((r) => `<tr>${r.map((c, i) => `<td style="padding:8px;border-bottom:1px solid #f0f1f3;text-align:${i ? 'right' : 'left'}">${c}</td>`).join('')}</tr>`).join('')}</table>`;
}

// Sent to the BUSINESS (not their customer): a draft invoice is waiting in Xero for approval.
function invoiceDraftEmail(client, { job, invoiceNumber, total, note, xeroUrl }) {
  const body = `<h2 style="margin-top:0">Draft invoice ready to approve</h2>
<p>We've created a <strong>draft</strong> invoice in Xero for <strong>${e(job.customerName)}</strong>. Nothing has been sent to your customer. Approve it in Xero when you're happy.</p>
${table([['Job', e(job.jobId)], ['Customer', e(job.customerName)], ['Invoice', e(invoiceNumber || 'Draft')], ['Total', gbp(total)]])}
${note ? `<p style="background:#fff7e6;border-left:4px solid #f59e0b;padding:10px"><strong>Keystone AI note:</strong> ${e(note)}</p>` : ''}
${xeroUrl ? `<p><a href="${e(xeroUrl)}" style="background:#1d2433;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none">Review in Xero</a></p>` : ''}
<p style="font-size:13px;color:#6b7280">Payment options shown to customers: ${e(client.invoice.paymentOptions || 'as set in Xero')}</p>`;
  return shell(client, 'Draft invoice ready', body);
}

function quoteDraftEmail(client, q, approveUrl) {
  const rows = q.lines.map((l) => [e(l.description), gbp(l.amount)]);
  rows.push(['<strong>Subtotal (ex VAT)</strong>', gbp(q.subtotal)], ['VAT', gbp(q.vat)], ['<strong>Total</strong>', `<strong>${gbp(q.total)}</strong>`]);
  const warn = q.belowMarginFloor ? `<p style="background:#fee2e2;border-left:4px solid #dc2626;padding:10px"><strong>Below your margin floor:</strong> estimated margin ${q.marginPct}% against a minimum of ${q.minMarginPct}%. Check the price before approving.</p>` : `<p style="font-size:13px;color:#059669">Estimated margin ${q.marginPct}% (minimum ${q.minMarginPct}%).</p>`;
  const body = `<h2 style="margin-top:0">Quote draft for your approval: ${e(q.ref)}</h2>
<p>For <strong>${e(q.customerName || 'customer')}</strong>: ${e(q.description)}</p>
${table(rows, ['Item', 'Price'])}
${warn}
${q.agentNotes ? `<p style="font-size:13px"><strong>How this was priced:</strong> ${e(q.agentNotes)}</p>` : ''}
