  if (response.stop_reason === 'refusal') return { ok: false, error: 'refusal' };
  if (response.stop_reason === 'max_tokens') return { ok: false, error: 'truncated' };
  if (response.stop_reason === 'pause_turn') return { ok: false, error: 'paused' };
